FILES = {'experiments/day17_evidence_figures.py': '"""Scientific figures from complete saved contrast tables; no outcome selection."""\nfrom pathlib import Path\n\nimport matplotlib\nmatplotlib.use(\'Agg\')\nimport matplotlib.pyplot as plt\nimport numpy as np\nimport pandas as pd\n\n\nFACTORS = [\'reset_lora_weights\', \'reset_head_weights\', \'reset_lora_optimizer\', \'reset_head_optimizer\']\nLABELS = [\'LoRA weights\', \'Classifier weights\', \'LoRA AdamW state\', \'Classifier AdamW state\']\nOUT = Path(\'figures/extended_audit\')\n\n\ndef save(fig, stem):\n    for extension in [\'png\', \'pdf\', \'svg\']:\n        fig.savefig(OUT / (stem + \'.\' + extension), dpi=220, bbox_inches=\'tight\')\n    plt.close(fig)\n\n\ndef read(path):\n    p = Path(path)\n    if not p.exists():\n        return pd.DataFrame()\n    try:\n        return pd.read_csv(p)\n    except pd.errors.EmptyDataError:\n        return pd.DataFrame()\n\n\ndef contrasts(frame, metric):\n    d = frame[frame.metric == metric].set_index(\'factor\').reindex(FACTORS)\n    if d[\'mean\'].isna().any():\n        raise RuntimeError(\'Cannot silently omit a reset factor\')\n    return d\n\n\ndef draw_points(ax, d, offset, label, color):\n    y = np.arange(4) + offset\n    ax.scatter(d[\'mean\'], y, color=color, s=27, label=label, zorder=3)\n    # Missing one-seed intervals remain visibly absent, never zero-width bars.\n    for position, (_, row) in zip(y, d.iterrows()):\n        if np.isfinite([row.ci_low, row.ci_high]).all():\n            ax.plot([row.ci_low, row.ci_high], [position, position], color=color, lw=1.3)\n\n\ndef main():\n    OUT.mkdir(parents=True, exist_ok=True)\n    captions = [\'# Extended development-audit figure captions\', \'\',\n        \'All intervals are descriptive 95% Student intervals over paired training seeds. \'\n        \'Both orders are averaged first. Fixed development examples have been repeatedly \'\n        \'examined; no population-sampling or multiplicity-adjusted claim follows. \'\n        \'No factor, regime or deployed rule is chosen by observed performance.\', \'\']\n    evidence = read(\'results/day15_seed_intervals.csv\')\n    if not evidence.empty:\n        evidence = evidence[evidence.kind == \'marginal\']\n        available = [r for r in [\'banking\', \'amazon\'] if r in set(evidence.regime)]\n        fig, axes = plt.subplots(len(available), 1, figsize=(8.7, 3.9*len(available)), squeeze=False)\n        for ax, regime in zip(axes[:,0], available):\n            part = evidence[evidence.regime == regime]\n            for metric, shift, label, color in [\n                (\'initial_loss_decrease\', -.19, \'Initial predictor effect\', \'#2468a2\'),\n                (\'local_improvement_increase\', 0, \'Local learning effect\', \'#bd5f1b\'),\n                (\'post_update_loss_decrease\', .19, \'Post-update total\', \'#208047\')]:\n                draw_points(ax, contrasts(part, metric), shift, label, color)\n            ax.axvline(0, color=\'black\', lw=.7)\n            ax.set_yticks(range(4), LABELS); ax.invert_yaxis()\n            ax.set_title(f\'{regime.upper()} | {int(part.n_seeds.min())} paired seeds\')\n            ax.set_xlabel(\'Loss effect of reset (positive = improvement)\')\n            ax.grid(axis=\'x\', alpha=.2); ax.legend(fontsize=8, loc=\'best\')\n        fig.tight_layout(); save(fig, \'weight_state_attribution\')\n        captions += [\'* `weight_state_attribution`: All four marginal reset effects, split into \'\n            \'initial prediction and one-step local learning contributions, plus their post-update \'\n            \'total. Artificial inherited optimizer states on reset weights are causal probes, \'\n            \'not recommended deployment states. Each verified observer reproduces the original \'\n            \'real learner bitwise. The source is the actual active package, not retrospectively \'\n            \'best feasible reuse.\', \'\']\n        fig, axes = plt.subplots(len(available), 2, figsize=(11, 3.8*len(available)), squeeze=False)\n        for row, regime in enumerate(available):\n            part = evidence[evidence.regime == regime]\n            for col, phase in enumerate([\'initial\', \'post\']):\n                ax = axes[row,col]\n                draw_points(ax, contrasts(part, phase+\'_group_mass_decrease\'), -.12,\n                            \'Group probability mass\', \'#2468a2\')\n                draw_points(ax, contrasts(part, phase+\'_within_group_decrease\'), .12,\n                            \'Within-group prediction\', \'#bd5f1b\')\n                ax.axvline(0, color=\'black\', lw=.7)\n                ax.set_yticks(range(4), LABELS); ax.invert_yaxis()\n                ax.set_title(regime.upper() + \' | \' + (\'Before update\' if phase == \'initial\' else \'After update\'))\n                ax.set_xlabel(\'Reset effect on cross-entropy component\')\n                ax.grid(axis=\'x\', alpha=.2); ax.legend(fontsize=8)\n        fig.tight_layout(); save(fig, \'label_group_attribution\')\n        captions += [\'* `label_group_attribution`: All marginal reset contrasts in label-group \'\n            \'probability loss and conditional within-group loss, before and after the matched \'\n            \'update. Group metadata is evaluator-only and never enters allocation or deployed \'\n            \'routing. BANKING has three disjoint observed label groups in a 77-output space; \'\n            \'Amazon uses the full shared binary group, so its group-mass component is zero. \'\n            \'The probability factorization is established prior work, not new theory.\', \'\']\n    grid = read(\'results/day17_static_pilot_grid.csv\')\n    if not grid.empty:\n        fig, ax = plt.subplots(figsize=(7.5,4.6))\n        for rank, color in [(8, \'#2468a2\'), (96, \'#bd5f1b\')]:\n            d = grid[grid[\'rank\'] == rank]\n            means = d.groupby(\'learning_rate\').final_macro_accuracy.mean().sort_index()\n            ax.plot(means.index, means, marker=\'o\', color=color, label=f\'Rank {rank} paired-order mean\')\n            ax.scatter(d.learning_rate, d.final_macro_accuracy, color=color, alpha=.5, marker=\'x\', s=30)\n        ax.set_xscale(\'log\'); ax.set_xlabel(\'AdamW learning rate\')\n        ax.set_ylabel(\'Final concept-macro development accuracy\')\n        ax.set_title(\'Seed 2026 tuning grid | both orders retained\')\n        ax.grid(alpha=.2); ax.legend(fontsize=8)\n        fig.tight_layout(); save(fig, \'static_pilot_grid\')\n        captions += [\'* `static_pilot_grid`: Every declared learning-rate candidate for both ranks \'\n            \'and both pilot orders; crosses show individual orders and lines show their averages. \'\n            \'The orders are not independent seed replicates. Rate selection uses only these \'\n            \'pilot outcomes, before paired development confirmations.\', \'\']\n    comparison = read(\'results/day17_tuned_static_paired_differences.csv\')\n    if not comparison.empty:\n        fig, ax = plt.subplots(figsize=(9,5.7))\n        d = comparison.sort_values([\'rank\',\'adaptive_rule\']).reset_index(drop=True)\n        labels = [f\'Rank {r["rank"]} | {r.adaptive_rule}\' for _,r in d.iterrows()]\n        for i, (_,r) in enumerate(d.iterrows()):\n            color = \'#2468a2\' if r[\'rank\'] == 8 else \'#bd5f1b\'\n            ax.scatter(100*r[\'mean\'], i, color=color, zorder=3)\n            if np.isfinite([r.ci_low,r.ci_high]).all():\n                ax.plot([100*r.ci_low,100*r.ci_high],[i,i],color=color,lw=1.5)\n        ax.axvline(0,color=\'black\',lw=.7);ax.set_yticks(range(len(d)),labels);ax.invert_yaxis()\n        ax.set_xlabel(\'Fixed-memory adaptive minus tuned static accuracy (percentage points)\')\n        ax.set_title(\'Every frozen adaptive rule and both tuned static ranks\')\n        ax.grid(axis=\'x\',alpha=.2);fig.tight_layout();save(fig,\'tuned_static_development_comparison\')\n        captions += [\'* `tuned_static_development_comparison`: Every adaptive routing rule versus \'\n            \'both pilot-selected static ranks. Positive differences favor the adaptive reference. \'\n            \'Actual head storage and compute differ even under the same retained-text budget. \'\n            \'This repairs a learning-rate comparator gap; it does not establish final-test or \'\n            \'named-method superiority.\', \'\']\n    Path(OUT/\'CAPTIONS.md\').write_text(\'\\n\'.join(captions)+\'\\n\')\n    print(\'EXTENDED_EVIDENCE_FIGURES_SAVED\', len(list(OUT.glob(\'*.png\'))), flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n', 'experiments/day17_manuscript_refresh.py': '"""Refresh the working draft from saved diagnostic evidence, never training data."""\nimport hashlib\nimport json\nfrom pathlib import Path\n\nimport pandas as pd\n\nfrom experiments.day5_report import markdown_table\n\n\nEXPECTED_DRAFT = \'2a3158350c783920f36c217f738c8061796b78beecaab5115d7cec3a0d2306a6\'\n\n\ndef replace_once(text, old, new):\n    if text.count(old) != 1:\n        raise RuntimeError(\'Working draft changed; inspect before applying the editorial update\')\n    return text.replace(old, new, 1)\n\n\ndef table(path, condition=None, columns=None):\n    p = Path(path)\n    if not p.exists():\n        return \'Pending: no saved verified comparison.\'\n    try:\n        frame = pd.read_csv(p)\n    except pd.errors.EmptyDataError:\n        return \'Pending: no complete comparison group.\'\n    if condition is not None:\n        frame = frame.loc[condition(frame)]\n    if frame.empty:\n        return \'Pending: no complete paired-seed comparison.\'\n    return markdown_table(frame if columns is None else frame[columns])\n\n\ndef main():\n    paper = Path(\'notes/paper_working_draft.md\')\n    if hashlib.sha256(paper.read_bytes()).hexdigest() != EXPECTED_DRAFT:\n        raise RuntimeError(\'Refusing to overwrite an independently edited manuscript\')\n    evidence = pd.read_csv(\'results/day10_initial_loss_comparison.csv\')\n    unique = evidence.drop_duplicates([\'regime\', \'architecture\', \'seed\'])\n    if len(unique) != 12 or set(unique.seed) != {2026, 2027, 2028}:\n        raise RuntimeError(\'All twelve frozen ranking controls are required\')\n    for name, expected in [(\'day8\', 44), (\'day12\', 11)]:\n        records = json.loads(Path(\'logs\', name + \'_queue_status.json\').read_text())\n        if sum(r[\'status\'] == \'completed\' for r in records) != expected:\n            raise RuntimeError(\'Frozen control coverage changed: \' + name)\n    records = json.loads(Path(\'logs/day14_fixed_memory_routing_status.json\').read_text())\n    if len(records) != 44 or any(r[\'status\'] != \'completed\' for r in records):\n        raise RuntimeError(\'All fixed-memory routing reloads are required\')\n    new_status = json.loads(Path(\'notes/day15_16_execution_status.json\').read_text())\n    coverage = {day: sum(r[\'status\'] == \'completed\' for r in new_status[\'jobs\'] if r[\'study\'] == day)\n                for day in [15, 16]}\n    verified = len(list(Path(\'results\').glob(\'day15_*_weight_moments/observer_verification.json\')))\n    if verified != coverage[15]:\n        raise RuntimeError(\'Execution and verified-observer coverage disagree\')\n    text = paper.read_text()\n    text = replace_once(text,\n        "Initial-loss ranking preserves the original pilot\'s decisions despite omitting the prospective learning-gain term from action ranking.",\n        \'Initial-loss ranking preserves BANKING decisions across three canonical-order development seeds, \'\n        \'but changes decisions on the third Amazon seed. Learning-gain relevance is therefore regime-dependent.\')\n    text = replace_once(text,\n        \'A future weight-only/moment-only factorial is required for their separate attribution.\',\n        \'The separately preregistered four-factor extension crosses LoRA weights, classifier weights, \'\n        \'LoRA AdamW state and classifier AdamW state in all sixteen cells. Every mature incoming batch \'\n        \'and both complementary query folds are retained. It additionally decomposes full-space \'\n        \'cross entropy into label-group probability loss and conditional within-group loss, using \'\n        \'evaluator-only group metadata. These are known probability identities, consistent with the \'\n        \'WP/TP factorization in Kim et al. (2022, 2023), not new theory. Only observers that reproduce \'\n        \'their full reference learner state and adapter tensors bitwise enter the analysis.\')\n    text = replace_once(text,\n        \'The four original pre-update-ranking pilots reproduce their original structural decisions. Prospective protected-memory checks remain in those pilots, so the finding concerns the action-ranking learning-gain term and does not demonstrate that all lookahead is unnecessary or that runtime improves.\',\n        \'All twelve frozen initial-loss ranking controls are complete: BANKING/Amazon, private/head-only, \'\n        \'and canonical-order seeds 2026–2028. BANKING has zero allocation disagreements in all six \'\n        \'comparisons. Amazon has zero in seeds 2026 and 2027, but 24 head-only and 30 private-package \'\n        \'decision disagreements in seed 2028. Under last-active prediction, the seed-2028 head-only \'\n        \'initial-loss and prospective-ranking accuracies are 77.34% and 79.95%; private-package \'\n        \'accuracies are 84.11% and 83.33%. These are individual development-seed results, not \'\n        \'seed-cluster significance claims. Prospective protected-memory checks remain in both \'\n        \'conditions. The finding concerns ranking only and supports neither removal of all lookahead \'\n        \'nor a runtime improvement claim.\\n\\n\' + markdown_table(unique[\n            [\'regime\', \'architecture\', \'seed\', \'allocation_disagreements\']]))\n    text = replace_once(text,\n        \'Fixed-memory replications and the larger fixed-capacity baseline remain **pending final analysis**. The rank-96 original pilot under the fixed training recipe performs poorly. This is a parameter sensitivity, not evidence that a properly tuned larger static alternative is inferior. Its training hyperparameters need a baseline tuning study with pilot/confirmation separation; no outcome-selected favorable rank or final-data tuning is justified.\',\n        \'All 44 fixed-memory trajectories, all 44 fixed-memory router reloads, and all 11 rank-96 \'\n        \'capacity trajectories are complete. The 512-total-text budget controls retained training \'\n        \'examples and caps pools at eight; it does not equalize model parameters, optimizer state \'\n        \'or prediction compute. Fixed versus per-adapter memory changes the private BANKING \'\n        \'centroid accuracy by +0.38 points (descriptive interval [0.12, 0.64]); Amazon changes are \'\n        \'small and uncertain. With this fixed text budget, private learned hard routing exceeds \'\n        \'the fixed rank-8 single by +5.35 points on BANKING ([0.82, 9.88]); probability mixture \'\n        \'gives +5.40 ([0.67, 10.14]). Amazon differences are -2.24 ([-5.97, 1.49]) and \'\n        \'-1.80 ([-4.40, 0.81]). All are development-stage descriptive five-seed comparisons, \'\n        \'with orders averaged inside seeds. The routing extension was introduced after earlier \'\n        \'deployment failure.\\n\\nThe larger static rank-96 baseline remains untuned: its final accuracy \'\n        \'is lower than rank 8 by 9.46 points ([-14.06, -4.86]) under the fixed recipe. Rank 96 \'\n        \'has 2,419,277 adaptation parameters, compared with 2,391,783 for three rank-8 private \'\n        \'packages; this is a particular storage scale, not universal resource matching. Poor \'\n        \'untuned performance cannot support superiority over a properly tuned static alternative. \'\n        \'A matched baseline tuning study with pilot/confirmation separation remains necessary.\')\n    text = replace_once(text,\n        \'Modern source-faithful method baselines, larger natural same-label adaptation regimes, separate classifier-weight/moment attribution and final evaluation are outstanding.\',\n        \'Modern source-faithful method baselines, larger natural same-label adaptation regimes \'\n        \'and complete-method confirmation evaluation remain outstanding. Separate classifier \'\n        \'weight/state attribution and BERT transfer are tracked below; coverage alone does not \'\n        \'establish a general mechanism.\')\n    text = replace_once(text,\n        \'## Figures and result sources\',\n        \'## 7. Preregistered development extensions\\n\\n\'\n        f\'The separate weight/state audit has {coverage[15]}/20 verified trajectories. \'\n        f\'The BERT allocation transfer study has {coverage[16]}/20 completed trajectories. \'\n        \'Every failed or incomplete attempt remains recorded. Empty comparisons are pending \'\n        \'and unpaired orders are excluded from seed intervals.\\n\\n\'\n        \'The BERT check changes the backbone, tokenizer, representations, frozen pooler and \'\n        \'classifier together. It uses a single linear classifier rather than the DistilBERT \'\n        \'trainable pre-classifier/classifier stack, but is not a causal isolation of classifier \'\n        \'design or a tuned BERT performance comparison.\\n\\n\'\n        + table(\'results/day16_bert_allocation_pairs.csv\') + \'\\n\\n\'\n        \'The following table retains all four marginal reset factors, both regimes, and each \'\n        \'declared metric. Positive contrasts mean lower initial/post-update loss or greater \'\n        \'local learning gain after reset. Conditional cells and interactions are in the full \'\n        \'Day-15 report. These averages describe the actual active source, not a retrospectively \'\n        \'chosen best feasible reuse candidate. The interval unit is a paired training seed; \'\n        \'the fixed development examples do not supply population-sampling uncertainty.\\n\\n\'\n        + table(\'results/day15_seed_intervals.csv\', lambda d: d.kind == \'marginal\',\n                [\'regime\', \'factor\', \'metric\', \'n_seeds\', \'mean\', \'ci_low\', \'ci_high\']) + \'\\n\\n\'\n        \'## 8. Related work and contribution boundary\\n\\n\'\n        \'Classifier recency bias is established in Supervised Contrastive Replay (Mai et al., \'\n        \'2021), which studies replacing softmax classifiers with nearest-class-mean prediction. \'\n        \'Logit and parameter calibration are also established in NLP continual learning \'\n        \'(Li et al., 2022, LPC). Kim et al. (2022) decompose class-incremental prediction into \'\n        \'within-task and task-id prediction; Kim et al. (2023), Eq.1, restate that factorization. \'\n        \'Neither recognizing classifier bias nor the label-group loss identity is our contribution.\\n\\n\'\n        \'Wang et al. (2026, Predicting Plasticity) already distinguish initial loss from normalized \'\n        \'future optimization gain. Lyle et al. (2025) study multiple causes of plasticity loss; \'\n        \'Hernandez-Garcia et al. (2026) compare weight and unit reinitialization. Prospective \'\n        \'optimization consequences, factorial diagnosis, and reset benefits are established. \'\n        \'The candidate contribution is an operational empirical audit of how classifier-bearing \'\n        \'allocation packages select resources, with optimizer-state attribution, cross-backbone \'\n        \'checks, deployment/resource controls, and explicit failure conditions. Novelty remains \'\n        \'provisional without the comparator and stronger-regime evidence.\\n\\n\'\n        \'Primary source links and precise scope are in `notes/novelty_audit_20261006.md` and \'\n        \'`notes/classifier_prior_audit_20261006.md`.\\n\\n\'\n        \'## Figures and result sources\')\n    tuning_status = Path(\'notes/day17_static_tuning_execution.json\')\n    if tuning_status.exists():\n        state = json.loads(tuning_status.read_text())\n        pilots = sum(r[\'phase\'] == \'pilot\' and r[\'status\'] == \'completed\' for r in state[\'jobs\'])\n        confirmations = sum(r[\'phase\'] == \'confirmation\' and r[\'status\'] == \'completed\' for r in state[\'jobs\'])\n        addition = (\'## 9. Equal-grid tuning of static baselines\\n\\n\'\n            f\'The baseline repair has {pilots}/24 pilot trajectories and \'\n            f\'{confirmations}/20 paired development confirmations. \'\n            \'Ranks 8 and 96 receive the same six-rate, two-order pilot grid. Each rank\\\'s rate \'\n            \'is selected using only seed 2026, then committed before seeds 2027–2031. \'\n            \'The existing adaptive outcomes and fixed development examples had already been \'\n            \'examined. This addresses learning-rate tuning within a declared grid, not an \'\n            \'untouched final evaluation or exhaustive hyperparameter search.\\n\\n\'\n            + table(\'results/day17_tuned_static_paired_differences.csv\') + \'\\n\\n\'\n            \'All static ranks and adaptive rules are retained, with both orders averaged within \'\n            \'each seed. Actual parameter storage, optimizer state and prediction compute remain \'\n            \'different resources. The full grid, every trajectory, selected rates and resource \'\n            \'counts are in `notes/day17_static_tuning_results.md`.\\n\\n\')\n        text = replace_once(text, \'## Figures and result sources\', addition + \'## Figures and result sources\')\n        if state.get(\'complete\'):\n            text = replace_once(text,\n                \'A matched baseline tuning study with pilot/confirmation separation remains necessary.\',\n                \'The subsequent equal-grid rate study below addresses this tuning gap within \'\n                \'its declared development protocol. Broader hyperparameter choices and final \'\n                \'complete-method confirmation remain untested.\')\n    # Cross-check rounded editorial figures against the complete tables.\n    memory = pd.read_csv(\'results/day8_memory_paired_differences.csv\')\n    row = memory[(memory.regime == \'banking\') & (memory.architecture == \'private\')\n                 & (memory.rule == \'frozen_centroid\')].iloc[0]\n    if abs(row[\'mean\'] - .00377) > .00001:\n        raise RuntimeError(\'Fixed-memory editorial values no longer match saved evidence\')\n    comparisons = pd.read_csv(\'results/day14_memory_routing_paired_differences.csv\')\n    row = comparisons[(comparisons.regime == \'banking\') & (comparisons.architecture == \'private\')\n                      & (comparisons.rule == \'linear_hard\') & (comparisons.contrast == \'fixed_minus_single\')].iloc[0]\n    if abs(row[\'mean\'] - .053512) > .000001:\n        raise RuntimeError(\'Router editorial values no longer match saved evidence\')\n    paper.write_text(text)\n    Path(\'notes/manuscript_refresh_receipt.json\').write_text(json.dumps({\n        \'previous_manuscript_sha256\': EXPECTED_DRAFT,\n        \'new_manuscript_sha256\': hashlib.sha256(paper.read_bytes()).hexdigest(),\n        \'diagnostic_coverage\': coverage,\n        \'training_or_test_data_accessed\': False,\n        \'scope\': \'editorial refresh from existing saved development evidence\'}, indent=2) + \'\\n\')\n    print(\'MANUSCRIPT_EVIDENCE_REFRESH_SAVED\', coverage, flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n', 'experiments/day17_static_replay_gate.py': '"""Check the scoped rank/rate wrapper against a current exact reference."""\nimport argparse\nimport hashlib\nimport json\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\nimport torch\nfrom safetensors.torch import load_file\n\nfrom experiments.day3_action_utility_unit import nested_equal\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\'--output\', required=True)\n    args = parser.parse_args()\n    original = Path(\'results/day12_banking_private_single_rank96_seed2031_b_first\')\n    candidate = Path(args.output)\n    provenance = [json.loads((folder / \'provenance.json\').read_text()) for folder in [original, candidate]]\n    assert provenance[0][\'stream_sha256\'] == provenance[1][\'stream_sha256\']\n    assert provenance[0][\'model_revision\'] == provenance[1][\'model_revision\']\n    routes = [pd.read_csv(folder / \'routing.csv\') for folder in [original, candidate]]\n    columns = [\'step\', \'adapter\', \'decision\', \'train_executed\', \'num_adapters\', \'replay_items\']\n    assert len(routes[0]) == len(routes[1]) == 80\n    assert routes[0][columns].equals(routes[1][columns])\n    assert np.allclose(routes[0].loss, routes[1].loss, atol=1e-6, rtol=0)\n    states = [torch.load(folder / \'checkpoint/learner_state.pt\', map_location=\'cpu\', weights_only=False)\n              for folder in [original, candidate]]\n    assert nested_equal(*states), \'Scoped baseline port changed the final real learner state\'\n    files = list((original / \'checkpoint/adapters\').rglob(\'*.safetensors\'))\n    assert files\n    for path in files:\n        assert nested_equal(load_file(str(path)), load_file(str(candidate / path.relative_to(original))))\n    receipt = {\'status\': \'passed\', \'reference\': str(original), \'candidate\': str(candidate),\n               \'stream_sha256\': provenance[0][\'stream_sha256\'], \'bitwise_final_state_equal\': True,\n               \'bitwise_adapter_tensors_equal\': True,\n               \'maximum_training_loss_difference\': float(np.max(abs(routes[0].loss-routes[1].loss))),\n               \'reference_state_sha256\': hashlib.sha256((original / \'checkpoint/learner_state.pt\').read_bytes()).hexdigest()}\n    (candidate / \'static_replay_verification.json\').write_text(json.dumps(receipt, indent=2) + \'\\n\')\n    print(\'STATIC_TUNING_BITWISE_REPLAY_GATE_PASS\', flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n', 'experiments/day17_static_tuning_report.py': '"""Retain the complete baseline grid and all paired development rules."""\nimport json\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\n\nfrom experiments.day5_report import markdown_table\nfrom experiments.day6_diagnostic_report import interval\n\nRATES = [2e-5, 5e-5, 1e-4, 2e-4, 4e-4, 8e-4]\n\n\ndef select_pilot_rates(data):\n    actual = set(zip(data[\'rank\'], data.learning_rate, data.order))\n    expected = {(rank, rate, order) for rank in [8, 96] for rate in RATES\n                for order in [\'canonical\', \'b_first\']}\n    if (len(data) != 24 or actual != expected or set(data.seed) != {2026}\n            or not (data.updates == 80).all() or not np.isfinite(data.final_macro_accuracy).all()\n            or not data.final_macro_accuracy.between(0, 1).all()):\n        raise RuntimeError(\'Pilot selection requires the complete exact 24-run grid\')\n    grid = [{\'rank\': int(rank), \'learning_rate\': float(rate),\n             \'pilot_accuracy_mean\': float(group.final_macro_accuracy.mean())}\n            for (rank, rate), group in data.groupby([\'rank\', \'learning_rate\'])]\n    selected = {str(rank): sorted([r for r in grid if r[\'rank\'] == rank],\n                 key=lambda r: (-r[\'pilot_accuracy_mean\'], r[\'learning_rate\']))[0][\'learning_rate\']\n                for rank in [8, 96]}\n    return selected, grid\n\n\ndef final_accuracy(folder):\n    p = json.loads((folder / \'provenance.json\').read_text())\n    s = json.loads((folder / \'summary.json\').read_text())\n    if s[\'status\'] != \'completed\' or s[\'steps\'] != 80:\n        raise RuntimeError(\'Incomplete baseline is not an observed outcome\')\n    f = pd.read_csv(folder / \'label_free_eval.csv\')\n    f = f[(f.step == 80) & (f.rule == \'last_active\')]\n    if len(f) != 3:\n        raise RuntimeError(\'Missing full-space concept predictions\')\n    return p, s, float(f.accuracy.mean())\n\n\ndef pilot_table():\n    rows = []\n    for folder in sorted(Path(\'results\').glob(\'day17_pilot_rank*_lr*_seed2026_*\')):\n        if not (folder / \'summary.json\').exists():\n            continue\n        if json.loads((folder / \'summary.json\').read_text())[\'status\'] != \'completed\':\n            continue\n        p, s, accuracy = final_accuracy(folder)\n        rows.append({\'run\': folder.name, \'rank\': p[\'lora_rank\'], \'learning_rate\': p[\'learning_rate\'],\n                     \'seed\': 2026, \'order\': p[\'args\'][\'order\'], \'final_macro_accuracy\': accuracy,\n                     \'updates\': s[\'learning_updates\']})\n    return pd.DataFrame(rows)\n\n\ndef main():\n    pilots = pilot_table()\n    selection_path = Path(\'notes/day17_static_rate_selection.json\')\n    selection = json.loads(selection_path.read_text()) if selection_path.exists() else None\n    report = [\'# Tuned fixed-capacity development baselines\', \'\',\n              f\'Completed pilot trajectories: {len(pilots)}/24.\', \'\',\n              \'The full equal-budget learning-rate grid and its pilot-only selection rule were \'\n              \'committed before tuning outcomes. Both ranks and all adaptive deployment rules \'\n              \'are retained. Development examples and the adaptive reference outcomes were \'\n              \'already examined; this is not untouched final evaluation.\', \'\']\n    if not pilots.empty:\n        pilots.to_csv(\'results/day17_static_pilot_grid.csv\', index=False)\n        report += [\'## Every pilot\', \'\', markdown_table(pilots), \'\']\n    comparisons, incomplete = [], []\n    for folder in sorted(Path(\'results\').glob(\'day17_confirm_rank*_lr*_seed*\')):\n        if not (folder / \'summary.json\').exists() or json.loads((folder / \'summary.json\').read_text())[\'status\'] != \'completed\':\n            incomplete.append(folder.name)\n            continue\n        if selection is None:\n            raise RuntimeError(\'Baseline confirmation has no frozen selection receipt\')\n        p, s, accuracy = final_accuracy(folder)\n        rank, seed, order = p[\'lora_rank\'], p[\'args\'][\'seed\'], p[\'args\'][\'order\']\n        if p[\'learning_rate\'] != selection[\'selected_rates\'][str(rank)]:\n            raise RuntimeError(\'Confirmation rate differs from the pilot-only selection\')\n        reference = Path(f\'results/day8_banking_private_cau_seed{seed}_{order}_fixed512\')\n        rp = json.loads((reference / \'provenance.json\').read_text())\n        rs = json.loads((reference / \'summary.json\').read_text())\n        if p[\'stream_sha256\'] != rp[\'stream_sha256\'] or rs[\'status\'] != \'completed\':\n            raise RuntimeError(\'Unpaired adaptive/static stream\')\n        f = pd.read_csv(reference / \'label_free_eval.csv\')\n        f = f[f.step == 80]\n        learned = pd.read_csv(reference / \'learned_routing.csv\')\n        for rule, group in pd.concat([f, learned], ignore_index=True).groupby(\'rule\'):\n            if len(group) != 3:\n                raise RuntimeError(\'Adaptive rule has incomplete concept coverage\')\n            adaptive = float(group.accuracy.mean())\n            r = s[\'resources\']\n            comparisons.append({\'rank\': rank, \'learning_rate\': p[\'learning_rate\'], \'seed\': seed,\n                \'order\': order, \'adaptive_rule\': rule, \'static_accuracy\': accuracy,\n                \'adaptive_accuracy\': adaptive, \'adaptive_minus_static\': adaptive-accuracy,\n                \'static_adaptation_parameters\': r[\'lora_parameters\']+r[\'private_head_parameters\'],\n                \'adaptive_adaptation_parameters\': rs[\'resources\'][\'lora_parameters\']+rs[\'resources\'][\'private_head_parameters\'],\n                \'static_optimizer_bytes\': r[\'optimizer_state_bytes\'],\n                \'adaptive_optimizer_bytes\': rs[\'resources\'][\'optimizer_state_bytes\'],\n                \'static_training_texts\': r[\'replay_items\'],\n                \'adaptive_training_texts\': rs[\'resources\'][\'replay_items\'],\n                \'static_training_seconds\': s[\'timing\'][\'live_training_seconds\'],\n                \'static_evaluation_seconds\': s[\'timing\'][\'evaluation_seconds\'],\n                \'static_gpu_peak_allocated_bytes\': r[\'gpu_peak_allocated_bytes\']})\n    if selection:\n        report += [\'## Frozen pilot selection\', \'\', markdown_table(pd.DataFrame(selection[\'grid_summary\'])), \'\',\n                   \'Selected rates: \' + json.dumps(selection[\'selected_rates\'], sort_keys=True) + \'.\', \'\']\n    report += [f\'Completed paired-development static trajectories: {len(comparisons)//5}/20; \'\n               f\'incomplete attempts: {incomplete}.\', \'\']\n    if comparisons:\n        frame = pd.DataFrame(comparisons)\n        frame.to_csv(\'results/day17_tuned_static_comparisons.csv\', index=False)\n        seed_rows, differences = [], []\n        for (rank, rule), group in frame.groupby([\'rank\', \'adaptive_rule\']):\n            complete = group.groupby(\'seed\').filter(lambda g: len(g) == 2 and set(g.order) == {\'canonical\', \'b_first\'})\n            for seed, pair in complete.groupby(\'seed\'):\n                seed_rows.append({\'rank\': rank, \'adaptive_rule\': rule, \'seed\': seed,\n                                  \'adaptive_minus_static\': pair.adaptive_minus_static.mean(),\n                                  \'static_accuracy\': pair.static_accuracy.mean(),\n                                  \'adaptive_accuracy\': pair.adaptive_accuracy.mean()})\n            values = complete.groupby(\'seed\').adaptive_minus_static.mean()\n            if len(values):\n                differences.append({\'rank\': rank, \'adaptive_rule\': rule, **interval(values)})\n        pd.DataFrame(seed_rows).to_csv(\'results/day17_tuned_static_seed_values.csv\', index=False)\n        summary = pd.DataFrame(differences)\n        summary.to_csv(\'results/day17_tuned_static_paired_differences.csv\', index=False)\n        report += [\'## Every rule and rank\', \'\', markdown_table(summary), \'\',\n                   \'## Every trajectory and actual resource count\', \'\', markdown_table(frame), \'\']\n    report += [\'Intervals are descriptive over paired training seeds and fixed development examples. \'\n        \'Repeatedly evaluated orders, batches, and classes are not independent replicates. \'\n        \'This is a learning-rate study, not exhaustive hyperparameter optimization. Static and adaptive \'\n        \'models differ in classifier multiplicity and update/inference compute. Equal retained-text \'\n        \'budgets are not universal resource matching. No modern named-method or final-test claim follows.\']\n    Path(\'notes/day17_static_tuning_results.md\').write_text(\'\\n\'.join(report) + \'\\n\')\n    print(\'STATIC_TUNING_REPORT_SAVED\', len(pilots), \'pilots\', len(comparisons)//5, \'confirmations\', flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n', 'experiments/day17_static_tuning.py': '"""Scoped static-rank/rate port of the unchanged Day-12 trainer."""\nimport argparse\nimport hashlib\nimport json\nimport math\nfrom pathlib import Path\nimport sys\n\nimport numpy as np\nimport pandas as pd\nfrom peft import LoraConfig\n\nfrom experiments import day12_capacity_recurrence as trainer\nfrom src.adapter_pool_cau_v1 import CAUV1AdapterPool\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\'--rank\', type=int, choices=[8, 96], required=True)\n    parser.add_argument(\'--learning-rate\', type=float, required=True)\n    parser.add_argument(\'--seed\', type=int, required=True)\n    parser.add_argument(\'--order\', choices=[\'canonical\', \'b_first\'], required=True)\n    parser.add_argument(\'--output\', required=True)\n    parser.add_argument(\'--deadline-utc\', required=True)\n    args = parser.parse_args()\n    if not math.isfinite(args.learning_rate) or args.learning_rate <= 0:\n        parser.error(\'A finite positive rate is required\')\n    supplied = {}\n\n    def config(**kwargs):\n        if kwargs[\'r\'] != 96 or kwargs[\'lora_alpha\'] != 192:\n            raise RuntimeError(\'Unexpected reference rank configuration\')\n        kwargs.update(r=args.rank, lora_alpha=2 * args.rank)\n        supplied[\'config\'] = dict(kwargs)\n        return LoraConfig(**kwargs)\n\n    def pool(**kwargs):\n        if kwargs[\'lr\'] != 2e-4:\n            raise RuntimeError(\'Unexpected reference optimizer rate\')\n        kwargs[\'lr\'] = args.learning_rate\n        answer = CAUV1AdapterPool(**kwargs)\n        if any(g[\'lr\'] != args.learning_rate for s in answer.states.values()\n               for g in s.optimizer.param_groups):\n            raise RuntimeError(\'The actual AdamW rate differs\')\n        return answer\n\n    trainer.LoraConfig = config\n    trainer.CAUV1AdapterPool = pool\n    sys.argv = [\'day12_capacity_recurrence\', \'--regime\', \'banking\', \'--architecture\', \'private\',\n                \'--policy\', \'single\', \'--seed\', str(args.seed), \'--order\', args.order,\n                \'--output\', args.output, \'--deadline-utc\', args.deadline_utc]\n    trainer.main()\n    folder = Path(args.output)\n    p = json.loads((folder / \'provenance.json\').read_text())\n    p.update(lora_rank=args.rank, lora_alpha=2 * args.rank, learning_rate=args.learning_rate,\n             tuning_spec_sha256=hashlib.sha256(Path(\'notes/day17_static_tuning_spec.md\').read_bytes()).hexdigest(),\n             tuning_wrapper_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),\n             override_scope=[\'lora_rank\', \'lora_alpha\', \'adamw_learning_rate\'],\n             actual_lora_config=supplied[\'config\'])\n    (folder / \'provenance.json\').write_text(json.dumps(p, indent=2) + \'\\n\')\n    summary = json.loads((folder / \'summary.json\').read_text())\n    route = pd.read_csv(folder / \'routing.csv\')\n    if (summary[\'status\'] != \'completed\' or len(route) != 80\n            or summary[\'learning_updates\'] != 80 or route.num_adapters.max() != 1\n            or set(route.decision) != {\'single_update\'} or route.replay_items.max() > 512\n            or not np.isfinite(route.loss).all()):\n        raise RuntimeError(\'Incomplete or invalid static attempt preserved\')\n    state = trainer.torch.load(folder / \'checkpoint/learner_state.pt\', map_location=\'cpu\', weights_only=False)\n    for opt in state[\'optimizers\'].values():\n        if any(g[\'lr\'] != args.learning_rate for g in opt[\'param_groups\']):\n            raise RuntimeError(\'Saved optimizer rate differs\')\n    evaluation = pd.read_csv(folder / \'label_free_eval.csv\')\n    for _, batch in evaluation.groupby([\'step\', \'concept\']):\n        if len(batch) != 3 or batch.accuracy.nunique() != 1 or np.ptp(batch.loss) > 1e-5:\n            raise RuntimeError(\'One-package predictor rules differ\')\n    print(\'STATIC_TUNING_TRAJECTORY_PASS\', args.rank, args.learning_rate, args.seed, args.order, flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n', 'experiments/day17_static_tuning_worker.py': '"""Run a preregistered equal-grid baseline repair and preserve every attempt."""\nfrom datetime import datetime, timezone\nimport fcntl\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport subprocess\nimport sys\n\n\nROOT = Path(\'/workspace/mitosis-interference\')\nBRANCH = \'day5-causal-audit\'\nRATES = [2e-5, 5e-5, 1e-4, 2e-4, 4e-4, 8e-4]\nLAUNCH_CUTOFF = datetime.fromisoformat(\'2026-10-07T03:00:00+00:00\')\nDEADLINE = \'2026-10-07T03:15:00+00:00\'\nSTATUS = Path(\'notes/day17_static_tuning_execution.json\')\nENV = os.environ.copy()\nENV.update(OMP_NUM_THREADS=\'8\', TOKENIZERS_PARALLELISM=\'false\',\n           GIT_TERMINAL_PROMPT=\'0\', GH_PROMPT_DISABLED=\'1\')\n\n\ndef now():\n    return datetime.now(timezone.utc).isoformat()\n\n\ndef write(path, data):\n    p = Path(path)\n    temporary = p.with_suffix(p.suffix + \'.tmp\')\n    temporary.write_text(json.dumps(data, indent=2) + \'\\n\')\n    temporary.replace(p)\n\n\ndef read(args):\n    return subprocess.check_output(args, env=ENV, text=True, timeout=90).strip()\n\n\ndef command(args, log=None):\n    print(\'RUN\', \' \'.join(args), flush=True)\n    return subprocess.run(args, env=ENV, stdin=subprocess.DEVNULL, stdout=log,\n                          stderr=subprocess.STDOUT if log else None).returncode\n\n\ndef preserve():\n    manifest = {}\n    for p in sorted(Path(\'results\').rglob(\'*\')):\n        if p.is_file() and \'checkpoint\' in p.parts:\n            digest = hashlib.sha256()\n            with p.open(\'rb\') as stream:\n                for block in iter(lambda: stream.read(8 * 1024 * 1024), b\'\'):\n                    digest.update(block)\n            manifest[str(p)] = {\'bytes\': p.stat().st_size, \'sha256\': digest.hexdigest()}\n    write(\'results/checkpoint_preservation_manifest.json\', manifest)\n    p = json.loads(Path(\'notes/preservation_status.json\').read_text())\n    p.update(checkpoint_files=len(manifest), checkpoint_bytes=sum(r[\'bytes\'] for r in manifest.values()),\n             new_snapshot_push_pending=True, github_ref_verified=False, remote_checkpoints_sha256_verified=False)\n    write(\'notes/preservation_status.json\', p)\n    if command([\'git\', \'add\', \'-A\']):\n        raise RuntimeError(\'Staging failed\')\n    if read([\'git\', \'status\', \'--porcelain\']):\n        if command([\'git\', \'commit\', \'-m\', \'Preserve pilot-selected fixed-capacity baseline progress\']):\n            raise RuntimeError(\'Progress commit failed\')\n    if command([\'git\', \'push\', \'origin\', BRANCH]):\n        raise RuntimeError(\'Progress push failed; preserve local state\')\n    head = read([\'git\', \'rev-parse\', \'HEAD\'])\n    assert read([\'git\', \'ls-remote\', \'origin\', \'refs/heads/\' + BRANCH]).split()[0] == head\n    assert not read([\'git\', \'status\', \'--porcelain\'])\n    print(\'STATIC_BASELINE_PROGRESS_PUSHED\', head, flush=True)\n\n\ndef run_job(records, name, rank, rate, seed, order, phase):\n    folder = Path(\'results\', name)\n    assert not folder.exists(), \'Refusing to overwrite \' + str(folder)\n    args = [sys.executable, \'-u\', \'-m\', \'experiments.day17_static_tuning\', \'--rank\', str(rank),\n            \'--learning-rate\', str(rate), \'--seed\', str(seed), \'--order\', order,\n            \'--output\', str(folder), \'--deadline-utc\', DEADLINE]\n    row = {\'name\': name, \'phase\': phase, \'status\': \'running\', \'started_utc\': now(), \'command\': args}\n    records.append(row)\n    write(STATUS, {\'jobs\': records, \'planned_research_jobs\': 44, \'github_save_pending\': True})\n    with Path(\'logs\', name + \'.txt\').open(\'x\') as log:\n        code = command(args, log)\n    row.update(status=\'completed\' if code == 0 else \'failed\', returncode=code, finished_utc=now())\n    if phase == \'replay_gate\' and code == 0:\n        with Path(\'logs\', name + \'_verify.txt\').open(\'x\') as log:\n            code = command([sys.executable, \'-u\', \'-m\', \'experiments.day17_static_replay_gate\',\n                            \'--output\', str(folder)], log)\n        row.update(replay_verification_returncode=code, status=\'completed\' if code == 0 else \'failed\')\n    if phase != \'replay_gate\':\n        with Path(\'logs\', name + \'_report.txt\').open(\'x\') as log:\n            report_code = command([sys.executable, \'-u\', \'-m\', \'experiments.day17_static_tuning_report\'], log)\n        if report_code:\n            row[\'report_failed\'] = True\n            code = report_code\n    write(STATUS, {\'jobs\': records, \'planned_research_jobs\': 44, \'github_save_pending\': True})\n    preserve()\n    print(\'STATIC_BASELINE_JOB\', name, row[\'status\'], flush=True)\n    if code:\n        raise RuntimeError(\'Baseline discrepancy preserved: \' + name)\n\n\ndef main():\n    os.chdir(ROOT)\n    ENV[\'MITOSIS_MODEL_REVISION\'] = json.loads(Path(\'notes/restart_20261006_preflight.json\').read_text())[\'backbone_revision\']\n    lock = open(\'/workspace/mitosis-restart-worker.lock\', \'a\')\n    fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)\n    assert read([\'git\', \'branch\', \'--show-current\']) == BRANCH\n    assert read([\'git\', \'remote\', \'get-url\', \'origin\']) == \'https://github.com/anitusiruk/mitosis-interference.git\'\n    assert not read([\'git\', \'status\', \'--porcelain\'])\n    assert not STATUS.exists(), \'An existing preserved attempt requires inspection\'\n    records, failed, stopped = [], False, False\n    try:\n        if datetime.now(timezone.utc) >= LAUNCH_CUTOFF:\n            stopped = True\n        else:\n            run_job(records, \'day17_rank96_reference_replay\', 96, 2e-4, 2031, \'b_first\', \'replay_gate\')\n        for rank in [8, 96]:\n            for rate in RATES:\n                for order in [\'canonical\', \'b_first\']:\n                    if stopped or datetime.now(timezone.utc) >= LAUNCH_CUTOFF:\n                        stopped = True\n                        break\n                    tag = int(round(rate * 1e6))\n                    run_job(records, f\'day17_pilot_rank{rank}_lr{tag}_seed2026_{order}\',\n                            rank, rate, 2026, order, \'pilot\')\n        pilots = [r for r in records if r[\'phase\'] == \'pilot\' and r[\'status\'] == \'completed\']\n        if len(pilots) == 24:\n            from experiments.day17_static_tuning_report import pilot_table, select_pilot_rates\n            data = pilot_table()\n            selected, grid = select_pilot_rates(data)\n            receipt = {\'selected_rates\': selected, \'grid_summary\': grid, \'selected_utc\': now(),\n                \'pilot_seed\': 2026, \'selection_metric\': \'final concept-macro accuracy, averaged paired pilot orders\',\n                \'tie_break\': \'smaller learning rate\', \'confirmation_outcomes_used\': False,\n                \'spec_sha256\': hashlib.sha256(Path(\'notes/day17_static_tuning_spec.md\').read_bytes()).hexdigest(),\n                \'pilot_grid_sha256\': hashlib.sha256(Path(\'results/day17_static_pilot_grid.csv\').read_bytes()).hexdigest()}\n            assert not Path(\'notes/day17_static_rate_selection.json\').exists()\n            write(\'notes/day17_static_rate_selection.json\', receipt)\n            preserve()  # Freeze the pilot-only choice on GitHub before confirmation.\n            for seed in range(2027, 2032):\n                for order in [\'canonical\', \'b_first\']:\n                    for rank in [8, 96]:\n                        if datetime.now(timezone.utc) >= LAUNCH_CUTOFF:\n                            stopped = True\n                            break\n                        rate = selected[str(rank)]\n                        tag = int(round(rate * 1e6))\n                        run_job(records, f\'day17_confirm_rank{rank}_lr{tag}_seed{seed}_{order}\',\n                                rank, rate, seed, order, \'confirmation\')\n    except Exception as error:\n        failed = True\n        write(\'notes/day17_static_tuning_failure.json\', {\'error\': repr(error), \'utc\': now()})\n        print(\'STATIC_BASELINE_HALTED\', repr(error), flush=True)\n    write(STATUS, {\'jobs\': records, \'planned_research_jobs\': 44, \'github_save_pending\': True,\n                   \'failed\': failed, \'administratively_stopped\': stopped})\n    preserve()\n    if command([sys.executable, \'-u\', \'-m\', \'experiments.finalize_github_save\']):\n        raise RuntimeError(\'Baseline remote checkpoint roundtrip failed\')\n    receipt = json.loads(Path(\'notes/github_save_verification.json\').read_text())\n    assert receipt[\'all_current_lfs_sha256_verified\']\n    p = json.loads(Path(\'notes/preservation_status.json\').read_text())\n    p.update(github_push_returncode=0, github_ref_verified=True, new_snapshot_push_pending=False,\n             remote_checkpoints_sha256_verified=True,\n             last_successful_github_snapshot_commit=receipt[\'preserved_snapshot_commit\'],\n             last_successful_github_save_verified_utc=receipt[\'verified_utc\'])\n    write(\'notes/preservation_status.json\', p)\n    complete = sum(r[\'phase\'] != \'replay_gate\' and r[\'status\'] == \'completed\' for r in records) == 44 and not failed\n    write(STATUS, {\'jobs\': records, \'planned_research_jobs\': 44, \'github_save_pending\': False,\n                   \'github_save_verified\': True, \'failed\': failed, \'complete\': complete,\n                   \'administratively_stopped\': stopped})\n    if command([\'git\', \'add\', \'notes/preservation_status.json\', str(STATUS)]):\n        raise RuntimeError(\'Final baseline receipt staging failed\')\n    if command([\'git\', \'commit\', \'-m\', \'Record verified checkpoint preservation for tuned static baselines\']):\n        raise RuntimeError(\'Final baseline receipt commit failed\')\n    if command([\'git\', \'push\', \'origin\', BRANCH]):\n        raise RuntimeError(\'Final baseline receipt push failed\')\n    head = read([\'git\', \'rev-parse\', \'HEAD\'])\n    assert read([\'git\', \'ls-remote\', \'origin\', \'refs/heads/\' + BRANCH]).split()[0] == head\n    assert not read([\'git\', \'status\', \'--porcelain\'])\n    print(\'STATIC_BASELINE_AND_GITHUB_SAVE_COMPLETE\', head, \'COMPLETE\', complete, \'FAILED\', failed, flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n', 'experiments/day17_static_report_integrity.py': '"""Analytic gate: pilot-only tie-breaking, complete grids and seed pairing."""\nimport os\nfrom pathlib import Path\nimport tempfile\n\nimport pandas as pd\n\nfrom experiments.day17_static_tuning_report import RATES, select_pilot_rates\n\n\ndef main():\n    rows = []\n    for rank in [8, 96]:\n        for rate in RATES:\n            for order in [\'canonical\', \'b_first\']:\n                good = (rank == 8 and rate in [1e-4, 2e-4]) or (rank == 96 and rate == 5e-5)\n                rows.append({\'rank\': rank, \'learning_rate\': rate, \'order\': order, \'seed\': 2026,\n                             \'updates\': 80, \'final_macro_accuracy\': .7 if good else .2})\n    pilots = pd.DataFrame(rows)\n    selected, grid = select_pilot_rates(pilots)\n    assert selected == {\'8\': 1e-4, \'96\': 5e-5} and len(grid) == 12\n    for bad in [pilots.iloc[:-1], pd.concat([pilots.iloc[:-1], pilots.iloc[:1]], ignore_index=True)]:\n        try:\n            select_pilot_rates(bad)\n        except RuntimeError:\n            pass\n        else:\n            raise AssertionError(\'An incomplete or duplicate grid was accepted\')\n    # Known paired differences and unpaired-order exclusion through the real report.\n    import json\n    from experiments.day17_static_tuning_report import main as report\n    previous = Path.cwd()\n    try:\n        with tempfile.TemporaryDirectory(prefix=\'day17_analytic_\') as directory:\n            os.chdir(directory)\n            Path(\'results\').mkdir(); Path(\'notes\').mkdir()\n            Path(\'notes/day17_static_rate_selection.json\').write_text(json.dumps({\n                \'selected_rates\': selected, \'grid_summary\': grid}))\n            for seed in range(2027, 2032):\n                for order in [\'canonical\', \'b_first\']:\n                    reference = Path(f\'results/day8_banking_private_cau_seed{seed}_{order}_fixed512\')\n                    reference.mkdir()\n                    resources = {\'lora_parameters\': 10, \'private_head_parameters\': 20,\n                                 \'optimizer_state_bytes\': 100, \'replay_items\': 512,\n                                 \'gpu_peak_allocated_bytes\': 1000}\n                    summary = {\'status\': \'completed\', \'steps\': 80, \'learning_updates\': 80,\n                               \'resources\': resources, \'timing\': {\'live_training_seconds\': 1, \'evaluation_seconds\': 2}}\n                    provenance = {\'stream_sha256\': f\'paired:{seed}:{order}\', \'args\': {\'seed\': seed, \'order\': order}}\n                    (reference/\'summary.json\').write_text(json.dumps(summary))\n                    (reference/\'provenance.json\').write_text(json.dumps(provenance))\n                    original = [{\'step\': 80, \'concept\': concept, \'rule\': rule, \'accuracy\': .6}\n                                for concept in [\'A\', \'B\', \'C\']\n                                for rule in [\'last_active\', \'uniform_probability\', \'frozen_centroid\']]\n                    learned = [{\'concept\': concept, \'rule\': rule, \'accuracy\': .6}\n                               for concept in [\'A\', \'B\', \'C\']\n                               for rule in [\'linear_hard\', \'linear_probability_mixture\']]\n                    pd.DataFrame(original).to_csv(reference/\'label_free_eval.csv\', index=False)\n                    pd.DataFrame(learned).to_csv(reference/\'learned_routing.csv\', index=False)\n                    for rank in [8, 96]:\n                        if rank == 96 and seed == 2031 and order == \'b_first\':\n                            continue\n                        folder = Path(f\'results/day17_confirm_rank{rank}_lr{int(selected[str(rank)]*1e6)}_seed{seed}_{order}\')\n                        folder.mkdir()\n                        p = dict(provenance, lora_rank=rank, learning_rate=selected[str(rank)])\n                        (folder/\'provenance.json\').write_text(json.dumps(p))\n                        (folder/\'summary.json\').write_text(json.dumps(summary))\n                        f = pd.DataFrame([{\'step\':80, \'rule\':\'last_active\', \'concept\':c, \'accuracy\':.5}\n                                          for c in [\'A\',\'B\',\'C\']])\n                        f.to_csv(folder/\'label_free_eval.csv\', index=False)\n            report()\n            intervals = pd.read_csv(\'results/day17_tuned_static_paired_differences.csv\')\n            assert len(intervals) == 10\n            assert set(intervals[intervals[\'rank\']==8].seed_clusters) == {5}\n            assert set(intervals[intervals[\'rank\']==96].seed_clusters) == {4}\n            assert abs(intervals[\'mean\'] - .1).max() < 1e-12\n            assert abs(intervals.ci_low - .1).max() < 1e-12\n            assert abs(intervals.ci_high - .1).max() < 1e-12\n    finally:\n        os.chdir(previous)\n    print(\'STATIC_REPORT_ANALYTIC_GATE_PASS pilot-only ties, missing grids, paired-seed exclusion\', flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n', 'notes/day17_static_tuning_spec.md': "# Matched learning-rate tuning for fixed-capacity baselines\n\nThis development extension was designed after the untuned rank-96 results and\nthe existing adaptive development results were inspected. It repairs a weak\ncomparator; it is not an untouched test or a source-faithful modern-method\nreproduction. Commit the full grid and selection rule before new tuning results.\n\n## Frozen protocol\n\nUse the unchanged Day-12 static trainer, with scoped overrides of only LoRA rank,\nalpha and the AdamW learning rate. All runs use DistilBERT at the explicitly pinned\nrestart revision, full 77-class BANKING predictions, the original train-derived\ndevelopment split, 80 incoming batches of 16, Q/V LoRA, zero LoRA dropout, gradient\nclipping 1.0, and one update per incoming batch. The classifier/pre-classifier is\nprivate and trainable. Each run has exactly one package and at most 512 retained\ntraining examples. Retained examples do not supply rehearsal updates. No expansion,\nadaptive selection, early stopping, or router tuning is used for these statics.\n\nCompare ranks 8 and 96 with alpha twice the rank. For EACH rank, use the SAME\nlearning-rate grid: 0.00002, 0.00005, 0.0001, 0.0002, 0.0004, 0.0008. Run both\ncanonical and B-first streams at pilot seed 2026: 24 pilot trajectories. Give every\ncandidate 80 updates and identical evaluation checkpoints. Retain every result,\nincluding poor runs. Halt and preserve any nonfinite or incomplete attempt.\n\nFor each rank separately, select the rate maximizing the average of the two pilot\norders' final concept-macro development accuracy under last-active prediction.\nTie-break by the smaller numerical learning rate. Require all 24 pilots before\nselection. Commit and push the selected rates, full pilot grid, source/spec hashes\nand selection receipt before running the selected rates at seeds 2027–2031, both\norders: 20 trajectories. These seed streams and development examples already\nsupport adaptive analyses, so call this paired development confirmation, never an\nuntouched final evaluation. Only pilot outcomes determine the baseline rates.\n\nPair to the completed private CAU fixed-512 trajectories, using exact stream hashes.\nReport all three original deployment rules and both frozen learned-routing rules\nof the adaptive reference. Static models have one classifier, so their routing\nrules are equivalent; verify this. Report both static ranks, every seed/order and\nall rules. Average orders within a seed for descriptive 95% Student-t intervals,\nwith all five seed values retained. No winner is selected from confirmation data.\n\nReport actual adaptation parameters, optimizer bytes, retained examples, GPU peak\nand training/evaluation times per trajectory. Equal text memory is not equal\nparameter storage or compute. Rank 96 approximates three rank-8 private packages,\nbut classifier multiplicity and actual pool size still differ. Timings are\ndescriptive under this shared pod, not a dedicated performance benchmark.\n\n## Implementation and preservation gates\n\nBefore pilot outcomes, replay the original rank-96, rate-0.0002 protocol at seed\n2031 B-first through the scoped wrapper. Require the current saved Day-12 action\nand loss trajectory, bitwise final learner state and saved adapter tensors to\nmatch. This checks the port against a reference produced on the current pinned\nenvironment; it does not establish historical backbone byte identity.\n\nNever overwrite existing outputs. A failed replay or research run halts this\nextension and preserves all attempts. Hold the shared GPU-worker lock and start\nonly after the previous forty diagnostics and their remote checkpoint verification\nfinish successfully. Launch new jobs before 2026-10-07 03:00 UTC; training deadline\nis 03:15 UTC. If coverage is administratively incomplete, record it and omit\nunpaired seed summaries. Save code, logs, raw outcomes and every checkpoint to the\nexisting anitusiruk/mitosis-interference day5-causal-audit branch, with GitHub ref\nverification after progress pushes and a fresh LFS roundtrip after the extension.\n", 'notes/classifier_prior_audit_20261006.md': "# Classifier and probability-factorization prior work\n\nFocused primary-source check, 2026-10-06. This supplements the novelty audit;\nit is not an exhaustive priority search. None of these papers has been reproduced\nas a matched baseline in this repository yet.\n\n* Mai, Li, Kim and Sanner, [Supervised Contrastive Replay: Revisiting the Nearest\n  Class Mean Classifier in Online Class-Incremental Continual Learning](https://arxiv.org/abs/2103.13885),\n  2021. The paper identifies softmax recency bias and studies replacing softmax\n  classification with nearest-class-mean prediction across replay methods. It\n  discusses probability mass favoring recent classes. Classifier bias and\n  classifier-dependent continual-learning outcomes are established observations;\n  they are not this project's novel claim.\n* Li, Wang, Li, Khan and Thuraisingham, [LPC: A Logits and Parameter Calibration\n  Framework for Continual Learning](https://aclanthology.org/2022.findings-emnlp.529/),\n  Findings of EMNLP 2022, pp.7142–7155. It combines logit and parameter calibration\n  without accessing previous task data and evaluates GLUE scenarios. NLP logit\n  calibration and old/new-model alignment are established. This project does not\n  claim to invent calibration or a stronger general-purpose NLP learner.\n* Kim, Xiao, Konishi, Ke and Liu, [A Theoretical Study on Solving Continual\n  Learning](https://arxiv.org/abs/2211.02633), NeurIPS 2022. It decomposes\n  class-incremental prediction into within-task prediction and task-id prediction,\n  and connects task identification with out-of-distribution detection.\n* Kim, Xiao, Konishi and Liu, [Learnability and Algorithm for Continual\n  Learning](https://proceedings.mlr.press/v202/kim23x.html), ICML 2023,\n  pp.16877–16896. Section 3, Eq.1 explicitly restates the product factorization\n  of within-task and task-id prediction, citing the 2022 work. Taking negative\n  logarithms gives the same elementary decomposition used by our label-group\n  audit. Our group-mass and conditional-loss measurements operationalize this\n  established identity on the logits of the allocation intervention; they do\n  not create a new theory, theorem or novel evaluation metric.\n* Hernandez-Garcia, Dohare, Luo and Sutton, [Reinitializing weights vs units for\n  maintaining plasticity in neural networks](https://proceedings.mlr.press/v330/hernandez-garcia26a.html),\n  CoLLAs 2026, pp.776–806. This is the published version of the previously cited\n  2025 preprint. Resetting parameters for plasticity and comparing reset resources\n  are established. One-step classifier reset benefit is not evidence of sustained\n  future plasticity.\n\n## Consequence for the contribution\n\nAn empirical allocation audit needs evidence about actual structural choices:\nthe correspondence between full-package and zero-LoRA classifier-only decisions,\nthe independent role of optimizer state, pre-update versus local learning effects,\nand conditions where these observations cease to hold. It must retain prediction\nbenefits of LoRA even when allocation is unchanged. Existing classifier-bias\nliterature explains why the mechanism is plausible; it does not by itself validate\nthis allocator's capacity interpretation or establish a defect in a named method.\n\nThe initial-loss ablation now supplies a boundary: all three BANKING canonical-order\ndevelopment seeds preserve decisions, but the third Amazon seed changes 24 head-only\nand 30 private-package decisions. The earlier all-zero pilot account cannot be\ngeneralized to both regimes or used to claim that lookahead is always unnecessary.\n\n## Author-source CABLE trace\n\nRead-only inspection at author repository commit\n`c72b9cfeb345c8d517f1266ceb2b0ebf8a02430e` found the top-level training calls in\n`models/cable.py:352–369`: select a policy action, assign a batch to the selected\nadapter, compute classifier cross entropy, use negative loss as reward, and update\nthe policy. `models/reinforcement.py:43–64` records categorical policy actions and\nrewards; `finish_episode` contains the discounted-return/clipped PPO procedure.\nThe previously inspected virtual-step/Fisher-change helper and the paper's Eq.10\nloss-ratio signal are distinct pieces. Merely transplanting one helper would not\nreproduce the full author method. This trace is a source-faithfulness constraint,\nnot a performance result or an accusation that the published method is defective.\nExact downloaded source hashes are in the preserved author-source receipt; full\nthird-party source was neither executed nor copied into this repository.\n"}
import os,json,hashlib,fcntl,time,subprocess,sys
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path('/workspace/mitosis-interference');os.chdir(ROOT)
ENV=os.environ.copy();ENV.update(GIT_TERMINAL_PROMPT='0',GH_PROMPT_DISABLED='1',OMP_NUM_THREADS='8',TOKENIZERS_PARALLELISM='false')
BRANCH='day5-causal-audit'
def now():return datetime.now(timezone.utc).isoformat()
def read(args):return subprocess.check_output(args,env=ENV,text=True,timeout=90).strip()
def command(args,log=None):
 print('FOLLOWON_RUN',' '.join(args),flush=True)
 return subprocess.run(args,env=ENV,stdin=subprocess.DEVNULL,stdout=log,stderr=subprocess.STDOUT if log else None).returncode
def push(message):
 assert command(['git','add','-A'])==0
 if read(['git','status','--porcelain']):assert command(['git','commit','-m',message])==0
 assert command(['git','push','origin',BRANCH])==0
 head=read(['git','rev-parse','HEAD']);assert read(['git','ls-remote','origin','refs/heads/'+BRANCH]).split()[0]==head
 assert not read(['git','status','--porcelain']);print('FOLLOWON_VERIFIED_GITHUB_HEAD',head,flush=True)
 return head
lock=open('/workspace/mitosis-restart-worker.lock','a')
while True:
 try:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 except BlockingIOError:
  if datetime.now(timezone.utc)>=datetime.fromisoformat('2026-10-07T03:25:00+00:00'):raise RuntimeError('Pending follow-on exceeded administrative cutoff without mutating the repository')
  print('WAITING_FOR_DIAGNOSTICS_AND_VERIFIED_SAVE',now(),flush=True);time.sleep(30);continue
 p=Path('notes/day15_16_execution_status.json')
 state=json.loads(p.read_text()) if p.exists() else {}
 if state.get('github_save_verified'):break
 fcntl.flock(lock,fcntl.LOCK_UN)
 if datetime.now(timezone.utc)>=datetime.fromisoformat('2026-10-07T03:25:00+00:00'):raise RuntimeError('Previous diagnostic save still unverified')
 print('WAITING_FOR_DIAGNOSTIC_SAVE_RECEIPT',now(),flush=True);time.sleep(30)
assert read(['git','branch','--show-current'])==BRANCH
assert read(['git','remote','get-url','origin'])=='https://github.com/anitusiruk/mitosis-interference.git'
assert not read(['git','status','--porcelain'])
assert read(['git','rev-parse','HEAD'])==read(['git','ls-remote','origin','refs/heads/'+BRANCH]).split()[0]
assert read(['gh','api','repos/anitusiruk/mitosis-interference','--jq','.permissions.push'])=='true'
for name,source in FILES.items():
 p=Path(name);assert not p.exists(),'Refusing to overwrite '+name
 p.write_text(source);print('FOLLOWON_INSTALL',name,hashlib.sha256(p.read_bytes()).hexdigest(),flush=True)
code=command([sys.executable,'-m','compileall','-q',*[name for name in FILES if name.endswith('.py')]])
with Path('logs/day17_static_report_analytic_gate.txt').open('x') as log:
 if code==0:code=command([sys.executable,'-u','-m','experiments.day17_static_report_integrity'],log)
Path('notes/day17_prelaunch_gate.json').write_text(json.dumps({'gate_returncode':code,'utc':now(),'research_outcomes_generated':False,'scope':'source compile and analytic selection/report fixtures'},indent=2)+'\n')
head=push('Freeze equal-grid static baseline tuning and document classifier prior work')
if code:raise RuntimeError('Analytic implementation gate failed; state preserved, research not launched')
allow_tuning=state.get('complete') and not state.get('failed') and datetime.now(timezone.utc)<datetime.fromisoformat('2026-10-07T03:00:00+00:00')
fcntl.flock(lock,fcntl.LOCK_UN)
if allow_tuning:
 with Path('/workspace/mitosis_day17_static_worker.log').open('x') as log:
  child=subprocess.Popen([sys.executable,'-u','-m','experiments.day17_static_tuning_worker'],env=ENV,stdin=subprocess.DEVNULL,stdout=log,stderr=subprocess.STDOUT)
  Path('/workspace/mitosis_day17_static_worker_pid.txt').write_text(str(child.pid)+'\n')
  print('PREREGISTERED_STATIC_BASELINE_WORKER_STARTED',child.pid,head,flush=True)
  child_code=child.wait();print('STATIC_BASELINE_WORKER_RETURN_CODE',child_code,flush=True)
else:print('STATIC_TUNING_NOT_LAUNCHED incomplete diagnostics, discrepancy, or launch cutoff',flush=True)
fcntl.flock(lock,fcntl.LOCK_EX)
assert not read(['git','status','--porcelain'])
if allow_tuning:
 status=json.loads(Path('notes/day17_static_tuning_execution.json').read_text())
 assert status.get('github_save_verified'),'Do not perform editorial writes over an unverified preservation failure'
# Editorial refresh does not access training data or alter any scientific outputs.
with Path('logs/day17_manuscript_refresh.txt').open('x') as log:
 editorial=command([sys.executable,'-u','-m','experiments.day17_manuscript_refresh'],log)
with Path('logs/day17_evidence_figures.txt').open('x') as log:
 figures=command([sys.executable,'-u','-m','experiments.day17_evidence_figures'],log)
Path('notes/day17_editorial_status.json').write_text(json.dumps({'manuscript_returncode':editorial,'figures_returncode':figures,'utc':now(),'scientific_trajectory_outputs_modified':False},indent=2)+'\n')
head=push('Update the manuscript and scientific figures from preserved diagnostic evidence')
print('FOLLOWON_RESEARCH_EDITORIAL_AND_GITHUB_SAVE_COMPLETE',head,'EDITORIAL',editorial,'FIGURES',figures,flush=True)
if editorial or figures:raise RuntimeError('Editorial discrepancy preserved for inspection')

